glsl3.frag:
precision highp float;
uniform sampler2D cc_spriteTexture;
uniform sampler2D foilGrain;
uniform sampler2D artFoilMask;
layout(std140) uniform GildLight {
  vec4 tiltFinish;
  vec4 foilStyle;
};
in vec2 uv;
in vec4 tint;
float lamp(float offset,float width) {
  float normalized=offset/width;
  return exp(-normalized*normalized);
}
float stampNoise(vec2 cell) {
  vec3 h=fract(vec3(cell.xyx)*vec3(.1031,.1030,.0973));
  h+=dot(h,h.yzx+33.33);
  return fract((h.x+h.y)*h.z);
}
vec4 frameReflection(vec4 die) {
  float metal=die.r, rim=die.g, inlay=die.b;
  float deposit=max(metal,max(rim,inlay))*die.a;
  if(deposit<.012)return vec4(0.);
