  float royal=tiltFinish.w;
  vec2 paper=(uv-vec2(.5,.46))*vec2(1.,1.417);
  vec2 cut=mat2(.91,.42,-.42,.91)*paper*vec2(42.,35.);
  cut.x+=.46*cut.y;
  vec2 leaf=floor(cut);
  vec2 local=fract(cut);
  float diagonal=step(local.x+local.y,1.);
  vec2 stamp=leaf+diagonal*vec2(43.,79.);
  vec2 normal=vec2(stampNoise(stamp),stampNoise(stamp+vec2(23.,71.)))*2.-1.;
  vec3 grain=texture(foilGrain,uv*vec2(.93,1.41)).rgb;
  float angleLight=dot(paper,vec2(.85,-.53))+.83*turn.x+.54*turn.y+.04;
  float grazing=clamp(length(turn)*1.8,0.,1.);
  float reflection=lamp(angleLight+.14*normal.x,.24);
  float ridge=lamp(angleLight+.035*normal.y-.06,.043);
  float scatter=lamp(dot(normal,vec2(.72,.57))-.88*turn.x+.72*turn.y-.09,.19)
               *(.30+.70*grain.b);
  float cutEdge=1.-smoothstep(.015,.11,abs(local.x+local.y-1.));
  float facet=metal*scatter*(.24+.85*reflection)*(.52+.48*grazing);
  float chase=rim*(.19+.86*ridge+.31*reflection);
  float counter=lamp(dot(paper,vec2(-.48,.88))-.67*turn.y+.47*turn.x-.18,.072);
  float fine=royal*metal*counter*(.18+.49*scatter+.26*cutEdge);
  vec2 burr=local-vec2(.32+.28*normal.x,.54+.24*normal.y);
  float pin=max(lamp(burr.x,.048)*lamp(burr.y,.30),lamp(burr.x,.29)*lamp(burr.y,.047));
  float glint=metal*pin*smoothstep(.47,.84,normal.x)*(.3+.7*grazing)
             *lamp(angleLight+.15*normal.y,.13)*(.48+.48*royal);
  float enamel=inlay*(.19+.64*reflection)*lamp(normal.y+.61*turn.x-.74*turn.y,.22);
  vec3 amber=vec3(.98,.60,.20);
  vec3 gold=mix(amber,vec3(1.,.86,.46),clamp(.27+scatter*.74,0.,1.));
  vec3 pearl=.73+.21*cos(6.2832*(vec3(.02,.65,.82)+normal.x*.33+turn.x*.43));
  vec3 light=mix(gold,vec3(1.,.98,.83),clamp(chase+ridge*.65+fine+glint,0.,1.));
  light=mix(light,pearl,clamp(enamel*(.30+.80*royal)+fine*.35,0.,.74));
  float coldFace=metal*(1.-scatter)*smoothstep(.12,.65,-normal.y+turn.x*.31);
  float shade=coldFace*grazing*reflection*(.35+.10*royal);
  float shine=facet*1.26+chase*.83+metal*ridge*.36+fine*1.2+enamel*.65+glint;
  vec3 reflected=mix(vec3(.39,.21,.068),light,shine/(shade+shine+.0001));
  return vec4(reflected,clamp((shade+shine)*die.a,0.,.97));
}
vec4 flatFoil(vec2 p,vec2 turn) {
  float sweep=dot(p,vec2(.90,-.43))+.66*turn.x+.46*turn.y+.055;
  float broad=lamp(sweep,.222);
  float crest=lamp(sweep-.015,.070);
  float returnEdge=lamp(sweep+.14,.055);
  float incidence=clamp(.53+2.85*sweep+.15*turn.x-.12*turn.y+.065*p.y,0.,1.);
  vec3 copper=vec3(1.,.46,.21), amber=vec3(1.,.82,.35);
  vec3 cyan=vec3(.24,.91,1.), violet=vec3(.68,.42,1.);
  vec3 pearl=mix(copper,amber,smoothstep(.08,.32,incidence));
  pearl=mix(pearl,cyan,smoothstep(.30,.52,incidence));
  pearl=mix(pearl,violet,smoothstep(.55,.84,incidence));
  float activity=smoothstep(.015,.46,length(turn));
  float order=lamp(sweep+.092,.044)+.70*lamp(sweep-.073,.036);
  float grating=.5+.5*cos(6.2831853*(71.*sweep+1.4*p.y+.13*sin(11.*p.y)));
  float grooves=order*pow(grating,7.)*activity;
  float hot=lamp(sweep-.016,.028);
  pearl=mix(pearl,vec3(.99,1.,.98),.33*hot+.22*grooves);
  float power=(.27*broad+.34*crest+.22*returnEdge)*(.48+.52*activity)+.18*grooves;
  return vec4(pearl,power);
}
vec4 crystalFoil(vec2 p,vec2 turn,float grain) {
  vec2 cut=mat2(.90,.44,-.44,.90)*p;
  cut=vec2(cut.x+.41*cut.y,cut.y)*vec2(15.5,19.);
  vec2 cell=floor(cut), at=fract(cut);
  float first=9., second=9.;
  vec2 winner=vec2(0.), facetPoint=vec2(0.);
  for (int j=-1;j<=1;j++) {
    for (int i=-1;i<=1;i++) {
      vec2 offset=vec2(float(i),float(j));
      vec2 id=cell+offset;
      vec2 seed=vec2(stampNoise(id+vec2(21.,9.)),stampNoise(id+vec2(5.,83.)));
      vec2 delta=offset+.12+.76*seed-at;
      float dist=dot(delta,delta);
      if (dist<first) {second=first;first=dist;winner=id;facetPoint=-delta;}
      else second=min(second,dist);
    }
  }
  vec2 facet=vec2(stampNoise(winner+vec2(31.,13.)),stampNoise(winner+vec2(79.,56.)));
  vec2 normal=facet*2.-1.;
  float angle=dot(normal,vec2(.76,.63))+.91*turn.x-.68*turn.y+.17*p.y;
  float wedge=dot(facetPoint,normalize(normal+vec2(.32,.18)));
  float catchLight=lamp(angle+.38*wedge,.22);
  float cleft=lamp(angle-.19+.28*wedge,.11)*smoothstep(-.09,.36,wedge);
  float cutEdge=1.-smoothstep(.017,.14,second-first);
  float box=lamp(dot(p,vec2(.77,-.47))+.73*turn.x+.44*turn.y,.39);
  float colorIndex=clamp(.47+.39*normal.y+.58*wedge+.14*turn.x-.10*turn.y,0.,1.);
  vec3 opal=mix(vec3(.32,.80,1.),vec3(.70,.48,.96),smoothstep(.06,.47,colorIndex));
  opal=mix(opal,vec3(1.,.71,.37),smoothstep(.47,.94,colorIndex));
  float hot=lamp(angle+.38*wedge,.073)*box;
  opal=mix(opal,vec3(1.,.99,.92),clamp(.34*hot+.41*hot*cutEdge+.15*cleft,0.,.80));
  float specular=(.64*catchLight+.36*cleft)*(.35+.59*box)*(.76+.24*grain);
  float seam=cutEdge*(.02+.19*catchLight+.08*cleft)*box;
  float activity=smoothstep(.01,.44,length(turn));
  return vec4(opal,(specular+seam)*(.57+.43*activity));
}
vec3 beatenLeaf(vec2 cellSpace) {
  vec2 id=floor(cellSpace);
  vec2 randomPair=vec2(stampNoise(id+vec2(11.,53.)),stampNoise(id+vec2(37.,6.)));
  vec2 loc=fract(cellSpace)-.5-(randomPair-.5)*.33;
  float orientation=6.2831853*randomPair.x;
  vec2 along=vec2(cos(orientation),sin(orientation));
  vec2 q=vec2(dot(loc,along),dot(loc,vec2(-along.y,along.x)));
  q/=vec2(.22+.22*randomPair.y,.085+.14*randomPair.x);
  float cut=max(max(abs(q.x),abs(q.y+.23*q.x)),abs(q.x-.57*q.y)*.82);
  float leaf=(1.-smoothstep(.77,1.17,cut))*smoothstep(.20,.38,randomPair.y);
  return vec3(leaf,randomPair.x,randomPair.y);
}
vec4 goldFlakeFoil(vec2 p,vec2 turn,float grain) {
  vec2 grainAxis=mat2(.84,.54,-.54,.84)*p;
  vec3 leaf=beatenLeaf(grainAxis*vec2(27.,32.)+vec2(7.2,3.1));
  vec3 dust=beatenLeaf(grainAxis.yx*vec2(71.,78.)+vec2(74.8,12.6));
  vec2 normals=vec2(dot(leaf.yz-.5,vec2(1.32,1.18)),dot(dust.yz-.5,vec2(1.56,-.84)));
  float yaw=.87*turn.x-.59*turn.y;
  float flash=lamp(normals.x-yaw,.23);
  float pin=lamp(normals.y-yaw,.17);
  float pool=lamp(dot(p,vec2(.73,.54))-.61*turn.x+.48*turn.y-.035,.38);
  float leafMetal=leaf.x*(.17+.84*flash)*(.65+.35*pool);
  float powder=dust.x*(.09+.71*pin)*(.60+.40*grain);
  float activity=smoothstep(.018,.39,length(turn));
  float weight=(leafMetal+powder*(1.-leafMetal))*(.65+.35*activity);
  vec3 honey=mix(vec3(.86,.46,.14),vec3(1.,.77,.32),.29+.63*leaf.z);
  vec3 reflected=mix(honey,vec3(1.,.96,.72),clamp(.59*flash+.45*pin*powder+.20*pool,0.,1.));
  return vec4(reflected,weight);
}
vec4 frag () {
  vec4 die=texture(cc_spriteTexture,uv);
  vec4 frame=frameReflection(die);
  vec2 varnish=texture(artFoilMask,uv).rg;
  if (varnish.r<.003) return vec4(frame.rgb,frame.a*tint.a);
  vec2 stock=(uv-vec2(.125,.11627907))/vec2(.75,.79069767);
  vec2 p=(stock-vec2(.5,.39))*vec2(1.,1.4166667);
  vec2 turn=tiltFinish.xy;
  vec4 finish;
  if (foilStyle.x<.5) {
    finish=flatFoil(p,turn);
  } else {
    float grain=texture(foilGrain,uv*vec2(.93,1.41)).b;
    if (foilStyle.x<1.5) finish=crystalFoil(p,turn,grain);
    else finish=goldFlakeFoil(p,turn,grain);
  }
  float coating=clamp(finish.a*varnish.r*(.89+.15*varnish.g),0.,.89);
  float film=coating*(1.-frame.a);
  float alpha=frame.a+film;
  vec3 color=(frame.rgb*frame.a+finish.rgb*film)/max(alpha,.0001);
  return vec4(color,alpha*tint.a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

